CREATE TABLE IF NOT EXISTS campaign_reward_distributions (campaign_id UUID PRIMARY KEY REFERENCES campaigns(id) ON DELETE CASCADE, merkle_root TEXT NOT NULL UNIQUE, total_amount_wei NUMERIC NOT NULL, created_by TEXT NOT NULL REFERENCES wallet_accounts(address), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS campaign_reward_allocations (campaign_id UUID NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE, leaf_index BIGINT NOT NULL, recipient_address TEXT NOT NULL REFERENCES wallet_accounts(address), amount_wei NUMERIC NOT NULL, merkle_proof JSONB NOT NULL, PRIMARY KEY(campaign_id,leaf_index), UNIQUE(campaign_id,recipient_address));
CREATE INDEX IF NOT EXISTS campaign_reward_allocations_recipient_idx ON campaign_reward_allocations(recipient_address,campaign_id);
